edits.after:
/* Try to get link status using Ethtool first. */
if (slave_dev->ethtool_ops->get_link) {
	/* Optimization: if the driver uses the generic ethtool_op_get_link,
	 * we can just check carrier directly. This avoids calling
	 * __linkwatch_sync_dev() which asserts locking, but we might be
	 * running lockless in bond_mii_monitor().
	 */
	if (slave_dev->ethtool_ops->get_link == ethtool_op_get_link) {
		ret = netif_carrier_ok(slave_dev) ? 1 : 0;
	} else {
		netdev_lock_ops(slave_dev);
		ret = slave_dev->ethtool_ops->get_link(slave_dev);
		netdev_unlock_ops(slave_dev);
	}

	return ret ? BMSR_LSTATUS : 0;
}

